function updatePlayerLabel(label: Phaser.GameObjects.Text | undefined, player: PlayerView, name: string, baseColor: string) {
  if (!label) return;
  const status = playerLevelStatus(player.level);
  const color = status?.legendary ? '#ffd575' : baseColor;
  if (label.style.backgroundColor !== color) label.setBackgroundColor(color);
  label.setText(status ? `${name} · ${translateText('ур.')} ${player.level}\n${status.symbol} ${status.title}` : name);
}

